const raw = $input.first().json;
const isManual = !raw.headers;
const p = raw.body || raw;
const sample = 'Summarize the key differences between REST and GraphQL in three bullet points.';
const task = (typeof p.task === 'string' && p.task.trim()) ? p.task.trim() : (isManual ? sample : '');

return [{
  json: {
    taskValid: !!task,
    validationError: task ? null : 'Request body must include a non-empty task string',
    taskId: p.taskId || ('route-' + Date.now()),
    task,
    context: typeof p.context === 'string' ? p.context : '',
    reqMaxCostUsd: Number(p.maxCostUsd) || 0,
    reqMinTier: Number(p.minTier) || 1,
    forceModel: typeof p.forceModel === 'string' ? p.forceModel : '',
    reqMinScore: Number(p.minQualityScore) || 0,
    reqMaxAttempts: Number(p.maxAttempts) || 0,
    startedAt: new Date().toISOString(),
    attemptIndex: 0,
    attempts: [],
    classifierCostUsd: 0,
    classifierTokens: { input: 0, output: 0 },
    judgeCostUsd: 0,
    judgeTokens: { input: 0, output: 0 },
    lastText: '',
    lastFeedback: ''
  }
}];

const s = $input.first().json;
const text = s.task + ' ' + s.context;
const lower = text.toLowerCase();
const words = text.split(/\s+/).filter(Boolean).length;

// Free heuristic used as a fallback if the classifier call fails
let c = words > 600 ? 4 : words > 150 ? 3 : words > 40 ? 2 : 1;
const needsCode = /\b(code|function|script|sql|regex|debug|api|class|python|javascript|typescript|bug)\b/.test(lower);
const needsReasoning = /\b(analy[sz]e|compare|trade-?off|architecture|strategy|prove|why|evaluate|plan|optimi[sz]e)\b/.test(lower);
if (needsCode) c = Math.max(c, 3);
if (needsReasoning) c = Math.max(c, 3);
const heuristic = {
  complexity: c,
  taskType: needsCode ? 'code' : needsReasoning ? 'analysis' : 'general',
  needsReasoning, needsCode,
  needsWebSearch: /\b(latest|current|today|news|recent|price of|who is the current)\b/.test(lower),
  longContext: words > 3000,
  estimatedOutputTokens: Math.min(3000, 200 + c * 300),
  risk: /\b(legal|medical|financial|contract|diagnos|lawsuit|tax)\b/.test(lower) ? 'high' : 'low',
  reasoning: 'heuristic fallback'
};

const shape = JSON.stringify({ complexity: 1, taskType: 'general | code | analysis | writing | extraction | summarization | qa | math', needsReasoning: false, needsCode: false, needsWebSearch: false, longContext: false, estimatedOutputTokens: 300, risk: 'low | medium | high', reasoning: 'one sentence' });
const system = 'You classify tasks for an LLM router so the cheapest capable model can be chosen. complexity is 1 (trivial lookup, rewrite, simple extraction) to 5 (deep multi-step reasoning, hard code, high-stakes analysis). Be honest: do not inflate complexity. Respond ONLY with valid JSON, no prose, matching exactly this shape: ' + shape;

return [{ json: { ...s, heuristic, classifierRequest: {
  model: s.classifierModel, max_tokens: 400, system,
  messages: [{ role: 'user', content: 'Task: ' + s.task + (s.context ? '\n\nContext (truncated):\n' + s.context.slice(0, 2000) : '') }]
} } }];

const state = $('Build Classifier Request').first().json;
const resp = $input.first().json;
const { classifierRequest, heuristic, ...rest } = state;

let catalog = [];
try { catalog = JSON.parse(state.modelCatalog); } catch (e) { throw new Error('modelCatalog is not valid JSON'); }
if (!catalog.length) throw new Error('modelCatalog is empty');
const priceOf = id => catalog.find(m => m.id === id) || { inputPer1M: 1, outputPer1M: 5 };

// Parse classification, fall back to heuristic
let cls = null; let classifierFailed = false;
try {
  if (resp.error || !Array.isArray(resp.content)) throw new Error('classifier call failed');
  const raw = resp.content.filter(b => b.type === 'text').map(b => b.text).join('');
  cls = JSON.parse(raw.replace(/```json|```/g, '').trim());
} catch (e) { classifierFailed = true; cls = heuristic; }
cls = {
  complexity: Math.min(5, Math.max(1, Math.round(Number(cls.complexity) || heuristic.complexity))),
  taskType: cls.taskType || 'general',
  needsReasoning: !!cls.needsReasoning, needsCode: !!cls.needsCode,
  needsWebSearch: !!cls.needsWebSearch, longContext: !!cls.longContext,
  estimatedOutputTokens: Math.min(4000, Math.max(100, Number(cls.estimatedOutputTokens) || heuristic.estimatedOutputTokens)),
  risk: ['low', 'medium', 'high'].includes(cls.risk) ? cls.risk : 'low',
  reasoning: cls.reasoning || ''
};

// Classifier cost
const u = (resp && resp.usage) || {};
const cIn = u.input_tokens || 0, cOut = u.output_tokens || 0;
const cp = priceOf(state.classifierModel);
const classifierCostUsd = cIn / 1e6 * cp.inputPer1M + cOut / 1e6 * cp.outputPer1M;

// Required tier from complexity, risk and needs
let need = cls.complexity <= 2 ? 1 : cls.complexity === 3 ? 2 : 3;
if (cls.risk === 'high') need = Math.min(3, need + 1);
if ((cls.needsReasoning || cls.needsCode) && cls.complexity >= 3) need = Math.max(need, 2);
need = Math.max(need, Math.min(3, state.reqMinTier || 1));

const estIn = Math.ceil((state.task.length + state.context.length) / 4);
const estOut = cls.estimatedOutputTokens;
const estCost = m => estIn / 1e6 * m.inputPer1M + estOut / 1e6 * m.outputPer1M;

let chainModels = [];
let budgetWarning = false;
const forced = state.forceModel && catalog.find(m => m.id === state.forceModel);
if (forced) {
  chainModels = [forced];
} else {
  const capable = catalog.filter(m => m.tier >= need && m.contextWindow >= (estIn * 1.2 + estOut) && (!cls.needsWebSearch || m.webSearch !== false));
  // cheapest model within each tier, ordered by tier = escalation chain
  const perTier = {};
  capable.sort((a, b) => estCost(a) - estCost(b)).forEach(m => { if (!perTier[m.tier]) perTier[m.tier] = m; });
  chainModels = Object.values(perTier).sort((a, b) => a.tier - b.tier);
  if (!chainModels.length) {
    chainModels = [catalog.slice().sort((a, b) => b.tier - a.tier || b.contextWindow - a.contextWindow)[0]];
    budgetWarning = true;
  }
  if (state.reqMaxCostUsd > 0) {
    const within = chainModels.filter(m => estCost(m) <= state.reqMaxCostUsd);
    if (within.length) chainModels = within; else budgetWarning = true;
  }
}
const attemptsAllowed = state.reqMaxAttempts || state.maxAttempts || 3;
chainModels = chainModels.slice(0, attemptsAllowed);

return [{ json: {
  ...rest,
  classification: cls, classifierFailed, requiredTier: need,
  chain: chainModels.map(m => m.id),
  chainDetail: chainModels.map(m => ({ id: m.id, tier: m.tier, estimatedCostUsd: Math.round(estCost(m) * 1e6) / 1e6 })),
  estInputTokens: estIn, estOutputTokens: estOut, budgetWarning,
  classifierCostUsd, classifierTokens: { input: cIn, output: cOut }
} }];

const s = $input.first().json;
const model = s.chain[s.attemptIndex];
const cls = s.classification;

const system = 'You are a capable assistant. Complete the task directly, accurately and concisely. Follow any requested format exactly. Do not mention internal routing.';
let user = 'Task: ' + s.task + (s.context ? '\n\nContext:\n' + s.context : '');
if (s.lastFeedback) user += '\n\nA previous attempt was rated too low. Reviewer feedback: ' + s.lastFeedback + '\nProduce an improved, complete answer.';

const req = { model, max_tokens: Math.min(4096, Math.max(600, s.estOutputTokens * 2)), system, messages: [{ role: 'user', content: user }] };
if (cls.needsWebSearch) req.tools = [{ type: 'web_search_20250305', name: 'web_search', max_uses: 3 }];

return [{ json: { ...s, executionRequest: req } }];

const s = $('Build Execution Request').first().json;
const { executionRequest, ...state } = s;
const resp = $input.first().json;

let catalog = [];
try { catalog = JSON.parse(state.modelCatalog); } catch (e) {}
const model = state.chain[state.attemptIndex];
const meta = catalog.find(m => m.id === model) || { tier: 0, inputPer1M: 0, outputPer1M: 0 };

const text = Array.isArray(resp.content) ? resp.content.filter(b => b.type === 'text').map(b => b.text).join('\n').trim() : '';
const failed = !!resp.error || !text;
const err = resp.error ? (resp.error.message || JSON.stringify(resp.error)) : 'empty response';
const u = resp.usage || {};
const inTok = u.input_tokens || 0, outTok = u.output_tokens || 0;
const costUsd = inTok / 1e6 * meta.inputPer1M + outTok / 1e6 * meta.outputPer1M;

const attempt = {
  attempt: state.attemptIndex + 1, model, tier: meta.tier,
  status: failed ? 'failed' : 'ok', error: failed ? err : null,
  inputTokens: inTok, outputTokens: outTok, costUsd: Math.round(costUsd * 1e6) / 1e6,
  score: null, feedback: null
};

const hasFallback = state.attemptIndex < state.chain.length - 1;
let nextAction = 'finish';
let attemptIndex = state.attemptIndex;
let lastFeedback = state.lastFeedback;
if (failed && hasFallback) { nextAction = 'escalate'; attemptIndex += 1; lastFeedback = ''; }
else if (!failed && state.judgeEnabled && hasFallback) { nextAction = 'judge'; }

return [{ json: { ...state, attempts: [...state.attempts, attempt], lastText: failed ? state.lastText : text, nextAction, attemptIndex, lastFeedback } }];

const s = $input.first().json;
const shape = JSON.stringify({ score: 0, feedback: 'one or two sentences on what is missing or wrong, or empty if fine' });
const system = 'You are a strict quality grader. Score how well the response completes the task from 1 (useless or wrong) to 10 (excellent, complete, correct). Judge correctness, completeness and following the requested format. Respond ONLY with valid JSON, no prose, matching exactly this shape: ' + shape;
const user = 'Task: ' + s.task + (s.context ? '\nContext: ' + s.context.slice(0, 1500) : '') + '\n\nResponse to grade:\n' + String(s.lastText).slice(0, 6000);
return [{ json: { ...s, judgeRequest: { model: s.judgeModel, max_tokens: 300, system, messages: [{ role: 'user', content: user }] } } }];

const s = $('Build Judge Request').first().json;
const { judgeRequest, ...state } = s;
const resp = $input.first().json;

let catalog = [];
try { catalog = JSON.parse(state.modelCatalog); } catch (e) {}
const jp = catalog.find(m => m.id === state.judgeModel) || { inputPer1M: 1, outputPer1M: 5 };
const u = resp.usage || {};
const jIn = u.input_tokens || 0, jOut = u.output_tokens || 0;
const judgeCost = jIn / 1e6 * jp.inputPer1M + jOut / 1e6 * jp.outputPer1M;

let score = null, feedback = '';
try {
  const raw = resp.content.filter(b => b.type === 'text').map(b => b.text).join('');
  const d = JSON.parse(raw.replace(/```json|```/g, '').trim());
  score = Math.min(10, Math.max(1, Number(d.score)));
  if (Number.isNaN(score)) score = null;
  feedback = String(d.feedback || '').slice(0, 600);
} catch (e) { score = null; }

const attempts = state.attempts.map((a, i) => i === state.attempts.length - 1 ? { ...a, score, feedback } : a);
const threshold = state.reqMinScore || state.minQualityScore || 7;
const hasFallback = state.attemptIndex < state.chain.length - 1;
// A failed judge call never forces an escalation
const escalate = score !== null && score < threshold && hasFallback;

return [{ json: {
  ...state, attempts, escalate,
  attemptIndex: escalate ? state.attemptIndex + 1 : state.attemptIndex,
  lastFeedback: escalate ? feedback : state.lastFeedback,
  judgeCostUsd: state.judgeCostUsd + judgeCost,
  judgeTokens: { input: state.judgeTokens.input + jIn, output: state.judgeTokens.output + jOut }
} }];

const s = $input.first().json;
let catalog = [];
try { catalog = JSON.parse(s.modelCatalog); } catch (e) {}
const round = n => Math.round(n * 1e6) / 1e6;

const okAttempts = s.attempts.filter(a => a.status === 'ok');
const finalAttempt = okAttempts[okAttempts.length - 1] || null;
const executionCostUsd = s.attempts.reduce((a, x) => a + x.costUsd, 0);
const totalCostUsd = executionCostUsd + s.classifierCostUsd + s.judgeCostUsd;

const base = catalog.find(m => m.id === s.premiumBaselineModel);
let premiumBaselineUsd = null, savingsUsd = null, savingsPct = null;
if (base && finalAttempt) {
  premiumBaselineUsd = finalAttempt.inputTokens / 1e6 * base.inputPer1M + finalAttempt.outputTokens / 1e6 * base.outputPer1M;
  savingsUsd = premiumBaselineUsd - totalCostUsd;
  savingsPct = premiumBaselineUsd > 0 ? Math.round(savingsUsd / premiumBaselineUsd * 1000) / 10 : null;
}

const status = !finalAttempt ? 'error' : (s.attempts.length > 1 ? 'completed_after_escalation' : 'completed');
const answer = finalAttempt ? s.lastText : 'No answer could be produced.';

const routingTrace = s.attempts.map(a => ({ attempt: a.attempt, model: a.model, tier: a.tier, status: a.status, qualityScore: a.score, costUsd: a.costUsd, feedback: a.feedback, error: a.error }));

// Optional ledger logging (compatible with the Execution Ledger workflow)
const ts = new Date().toISOString();
const events = [];
if (s.classifierTokens.input || s.classifierTokens.output) events.push({ runId: s.taskId, taskId: s.taskId, agentName: 'router-classifier', eventType: 'llm_call', model: s.classifierModel, inputTokens: s.classifierTokens.input, outputTokens: s.classifierTokens.output, timestamp: ts });
events.push({ runId: s.taskId, taskId: s.taskId, agentName: 'router', eventType: 'decision', decision: 'route:' + s.chain.join('>'), reasoning: 'complexity ' + s.classification.complexity + ', required tier ' + s.requiredTier + '. ' + s.classification.reasoning, timestamp: ts });
s.attempts.forEach(a => events.push({ runId: s.taskId, taskId: s.taskId, agentName: 'router-executor', eventType: 'llm_call', model: a.model, status: a.status, errorMessage: a.error, inputTokens: a.inputTokens, outputTokens: a.outputTokens, timestamp: ts }));
if (s.judgeTokens.input || s.judgeTokens.output) events.push({ runId: s.taskId, taskId: s.taskId, agentName: 'router-judge', eventType: 'llm_call', model: s.judgeModel, inputTokens: s.judgeTokens.input, outputTokens: s.judgeTokens.output, timestamp: ts });

return [{ json: {
  logToLedger: !!(s.ledgerUrl && String(s.ledgerUrl).trim()),
  ledgerUrl: s.ledgerUrl,
  ledgerPayload: { events },
  webhookResponse: {
    taskId: s.taskId, task: s.task, status, answer,
    modelUsed: finalAttempt ? finalAttempt.model : null,
    classification: s.classification,
    requiredTier: s.requiredTier,
    escalationChain: s.chainDetail,
    budgetWarning: s.budgetWarning,
    classifierFallbackUsed: s.classifierFailed,
    cost: {
      classifierUsd: round(s.classifierCostUsd), executionUsd: round(executionCostUsd), judgeUsd: round(s.judgeCostUsd),
      totalUsd: round(totalCostUsd),
      premiumBaselineUsd: premiumBaselineUsd === null ? null : round(premiumBaselineUsd),
      savingsUsd: savingsUsd === null ? null : round(savingsUsd), savingsPct
    },
    routingTrace,
    durationMs: Date.now() - new Date(s.startedAt).getTime()
  }
} }];
